import pytest

from stats import summarize


def test_list_input():
    result = summarize([1.0, 5.0, 2.0])
    assert result == {"total": 8.0, "count": 3, "peak": 5.0}


def test_generator_input():
    result = summarize(iter([1.0, 5.0, 2.0]))
    assert result == {"total": 8.0, "count": 3, "peak": 5.0}


def test_empty_iterable_raises():
    with pytest.raises(ValueError, match="empty"):
        summarize([])
    with pytest.raises(ValueError, match="empty"):
        summarize(iter([]))

